SELECT id, email, country, city, segment, signup_date, is_active, age, MIN(credit_limit) OVER (PARTITION BY country ORDER BY signup_date, id ROWS BETWEEN 3 PRECEDING AND CURRENT ROW) AS last4_min_credit_limit, SUM(credit_limit) OVER (PARTITION BY country ORDER BY signup_date, id ROWS BETWEEN 3 PRECEDING AND CURRENT ROW) AS last4_sum_credit_limit, MAX(credit_limit) OVER (PARTITION BY country ORDER BY signup_date, id ROWS BETWEEN 3 PRECEDING AND CURRENT ROW) AS last4_max_credit_limit, LAG(age, 2) OVER (PARTITION BY YEAR(signup_date), country ORDER BY signup_date, id) AS prev_age FROM customers WHERE is_active = TRUE;
